-- Western Plaguelands: creature abilities
-- Most of the zone's creatures (the Scourge, the Scarlet Crusade, the Forsaken and the Andorhal combatants, the Plaguebats and wildlife) had no AI or ran classic rows. Port their abilities from the
-- Cataclysm data, and from the classic data where Cataclysm has none, keeping the quest scripts already in place; gossip and quest
-- reward scripts of the references are left out. The creatures no reference scripts cast their sniffed spells (creature_template
-- spell1-8).

SET @ENTRIES := '1783,1784,1802,1815,1822,1824,1831,1837,1838,1839,1841,1843,1844,1847,1848,1849,1850,1851,1852,1854,1884,1885,4472,8596,10605,11194,12425,16143,44284,44315,44317,44318,44326,44328,44332,44432,44433,44440,44442,44443,44444,44445,44447,44448,44449,44450,44473,44474,44478,44479,44482,44484,44485,44486,44487,44488,44489,44551,44562,44944,44946,45047,45098,45101,45152,45153,45154,45155,45156,45166,45212,45239';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '44316,51535';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
